const CHIPS=['é','è','ê','à','â','î','ô','û','ç','’'];
const VOW=/^[aeiouyéèêàâîïôûh]/i;
// « que il » → « qu’il » ; « je ai » → « j’ai »
const qu=s=>(/^(il|ils|elle|elles|on|un|une)\b/i.test(s)?'qu’':'que ')+s;
const je=(s,f)=>s==='je'&&VOW.test(f)?'j’'+f:s+' '+f;

/* ---------- Phrases balisées : {ÉTIQUETTE|texte} ; un groupe est mis en gras et l’élève en donne la fonction, la classe ou le sens ---------- */
const MK=/\{([A-Z0-9]+)\|([^}]+)\}/g;
const unmark=t=>t.replace(MK,(a,g,x)=>x);
function marked(tpls,L,o={}){
  return d=>{
    for(let k=0;k<25;k++){
      const t=P(tpls);const toks=[...t.matchAll(MK)].filter(m=>L[m[1]]);
      if(!toks.length)continue;
      const m=P(toks);const lab=L[m[1]];const good=lab.n;
      const s=t.replace(MK,(a,g,x,off)=>off===m.index?`<b>${x}</b>`:x);
      const pool=(lab.bad||Object.keys(L).filter(x=>x!==m[1])).map(x=>L[x]?L[x].n:x).filter(x=>x!==good);
      return ch(`${o.q||'Quelle est la fonction du groupe en gras ?'}<br>« ${s} »`,good,pickN([...new Set(pool)],3),{expl:`« ${m[2]} » : ${lab.e}`,hint:o.hint});
    }
    return ch(`${o.q||'Quelle est la fonction du groupe en gras ?'}<br>« ${unmark(tpls[0])} »`,'sujet',['COD'],{expl:'Le groupe désigne celui qui fait l’action.'});
  };
}

